static void scr_wake_now(void)                         /* main.c: the crash screen, UPDATE, UBOOT */
{
    if (scrn.st != SCR_ON)
        lcd_wake_now();
    scrn.st = SCR_ON;
    scrn.idle = fm1_ms;
}

/* lcd.c: a rectangle about to go to the LCD; px (byte-swapped, stride pixels a row) or, for a fill, NULL and the
 * colour c */
static void mirror_lcd(uint32_t x, uint32_t y, uint32_t w, uint32_t h, const uint16_t *px, uint32_t stride, uint16_t c)
{
    uint32_t r, i, start = fm1_ms;
    if (!sm_on() || mirror_lost)
        return;
    for (r = 0; r < h; r++) {
        uint32_t t0 = fm1_ms;
        if (fm1_ms - start > 400u) {                   /* the host isn't keeping up: never hold the screen longer */
            mirror_lost = 1;
            return;
        }
        for (i = 0; i < w; i++)
            mirror_row[i] = px ? (uint16_t)((px[r * stride + i] >> 8) | (px[r * stride + i] << 8)) : c;
        while (!sm_rows(mirror_row, x, y + r, w, 1)) {   /* full: send some, briefly; else the whole screen later */
            sm_poll(fm1_ms, mirror_send);
            if (fm1_ms - t0 > 60u) {                     /* (a row is at most ~10 messages: a few ms at USB speed) */
                mirror_lost = 1;
                return;
            }
        }
    }
}

static uint32_t lowest_held(const track_t *t)           /* index of the lowest held note (the bass), NVOICE = none */
{
    uint32_t i, low = NVOICE;
    for (i = 0; i < NVOICE; i++)
        if (t->v[i].active && t->v[i].gate && (low == NVOICE || t->v[i].note < t->v[low].note))
            low = i;
    return low;
}

/* MONO / LEGATO / UNISON: one note on one voice (eight for UNISON, or the
 * engine's voice cap, spread by DETUNE over the same width) */
static void mono_play(track_t *t, uint32_t note, uint32_t vel, int retrig, int glide)
{
    uint32_t mode = (uint32_t)t->p[P_VOICE], nv = mode == V_UNISON ? trk_nvoice(t) : 1u, i;
    for (i = 0; i < nv; i++) {
        voice_t *v = &t->v[i];
        int32_t k = 2 * (int32_t)i - (int32_t)(nv - 1u);   /* -7 .. 7 */
        if (nv > 1u && nv < NVOICE)
            k = k * (NVOICE - 1) / (int32_t)(nv - 1u);      /* fewer voices: the outer ones as wide */
        v->fine = nv > 1u ? k * t->p[P_DETUNE] * 56 / 889 : 0;   /* up to ~±40 cents */
        if (retrig || !v->active || !v->gate) {
            if ((!v->active || v->stage == 4u) && !voice_room(t, i > 0))
                continue;                                   /* no room for this extra UNISON voice */
            /* level: about the same sum for 8 or 4 voices at random phases */
            voice_start(t, v, note, nv >= NVOICE ? vel * 36u / 100u : nv > 1u ? vel / 2u : vel, glide);
            v->side = (uint8_t)(i & 1u);                    /* ((1.3) SPREAD: the detuned voices alternate) */
            if (nv > 1u && i && !ENGINES[t->engine]->sampled) {   /* random start phases: */
                static uint32_t seed = 0x1234567u;          /* in phase they stack, evenly spread they cancel */
                seed = seed * 1664525u + 1013904223u;
                v->ph[0] += seed;
            }
        } else {                                            /* legato: new pitch, same envelope */
            v->note = (uint8_t)note;
            v->pitch16 = (int32_t)note * 16;
            v->mvel = t->m_vel;
            v->mrnd = t->m_rnd;
            if (vel > v->vel && nv == 1u)
                v->vel = (uint8_t)vel;
            glide_set(t, v, glide);
        }
    }
    t->mono_note = (uint8_t)note;
}

static void trk_note_off(track_t *t, uint32_t note)
{
    uint32_t i, k = 0, mode = trk_vmode(t);
    for (i = 0; i < t->xp_n; i++)                       /* not sounding yet (engine switch): forget it */
        if (t->xp_note[i] != note) {
            t->xp_note[k] = t->xp_note[i];
            t->xp_vel[k++] = t->xp_vel[i];
        }
    t->xp_n = (uint8_t)k;
    note = fol_off(t, note);                           /* ((2.1) the note it sounded; 255: another still sounds it) */
    mono_remove(t, note);                              /* a mode change must not retain a released key */
    if (mode != V_POLY) {
        uint32_t nv = mode == V_UNISON ? trk_nvoice(t) : 1u;
        if (t->mono_note == note) {
            uint32_t next = mono_pick(t);
            if (next) {                                 /* fall back to a held note, legato */
                mono_play(t, next, t->v[0].vel, 0, t->p[P_GLIDE] != 0);
            } else {
                for (i = 0; i < nv; i++)
                    if (t->v[i].gate) {
                        t->v[i].gate = 0;
                        t->v[i].stage = 3;
                    }
                t->mono_note = 0;
            }
        }
    }
    for (i = 0; i < NVOICE; i++)                        /* a fallback above already has its new pitch */
        if (t->v[i].note == note && t->v[i].gate) {
            t->v[i].gate = 0;
            t->v[i].stage = 3;
        }
}

static void arp_note_off(track_t *t, uint32_t note)
{
    if (!kb_sol_held(t, note))
        trk_note_off(t, note);
}

static void motion_begin(void)
{
    uint32_t k;
    for (k = 0; k < NTRK; k++) {
        motion_restore(&trk[k]);
        memcpy(motion_base[k], trk[k].p, sizeof trk[k].p);
    }
    motion_base_valid = (1u << NTRK) - 1u;
}

static void seq_start(void)
{
    uint32_t i;
#if BOARD_SMK37
    if (!song.g[G_CLOCK]) {                        /* (the TRS jack: Start, the first pulse with the first block) */
        smk_uart_tx_put(0xFAu);
        smk_clk_acc = beat_samples();
    }
#endif
    motion_begin();
    take_clear();                                  /* (Skiff) TAKES: a new log from PLAY */
    for (i = 0; i < NTRK; i++) {                   /* every track from its step 0, together */
        track_t *t = &trk[i];
        t->seq_idx = (uint16_t)(t->p[P_SLEN] - 1);
        t->seq_pos = 0x7FFFFFFF;                   /* step 0 fires on the first block */
        t->seq_cnt = 0;                            /* (Skiff) a run starts: its direction's first step */
        t->nud = 0;                                /* (Skiff) no NUDGE pending */
        t->rskip_n = 0;
        t->rh_n = 0;
        t->rat_left = 0;
        if (t->p[P_LTRIG] && t->p[P_LSYNC])        /* (#16) LFO 2 FREE + SYNC: in time with the bars from PLAY */
            t->lfo_ph = (uint32_t)t->p[P_LPHASE] << 25;
    }
    song.tick = 0;
    beat_pos = 0; beat_n = 0;                      /* the ARP LED's beat from the top too */
    launch_steps = 0; launch_pos = CLK_START;      /* (Skiff) the launch points' steps from the top, as the click's */
    clk_pos = CLK_START;                           /* the metronome's first beat with step 0 */
    song.playing = 1;
    slicer_start();                                /* slicer.c: its step 0 with the sequencer's */
    perf_start();                                  /* perform.c: its 1/16 grid too */
}

/* source s of the track: the per-track ones, the per-voice ones of the latest note-on */
static int32_t mod_tsrc(const track_t *t, uint32_t s, int32_t lfo)
{
    switch (s) {
    case MS_SH:
        return mod_sh(t);
    case MS_SLEW:                                       /* (1.3) the cycle before's value .. this one's, by the phase */
        return t->lfo_prev + (((mod_sh(t) - t->lfo_prev) * (int32_t)(t->lfo_ph >> 17)) >> 15);
    case MS_LFO:
        return lfo;
    case MS_ENV:
        return t->m_env;
    case MS_VEL:
        return t->m_vel * 258;
    case MS_KEY:
        return mod_key(t->m_key);
    case MS_RAND:
        return t->m_rnd;
    case MS_ENV2:                                       /* ((Skiff phase 9) the latest note's ENV 2) */
        return t->m_env2;
    case MS_MODW:
        return t->mw * 258;
    case MS_AT:
        return t->at * 258;
    default:
        return (127 - t->ex_off) * 258;
    }
}

/* seq.c keyboard_block: a layer key down / up (e: PF_*, PF_N = no effect) */
static void perf_press(uint32_t e, int down)
{
    if (e >= PF_N)
        return;
    if (perf_latch_on && e < PF_M1) {     /* FX LATCH: a press turns it on or off, letting go does nothing ((2.0, D 1A)
                                           * not a black key: its tap is the track's MUTE, held a cut, as unlatched) */
        if (down) {
            perf_latched ^= PF_BIT(e);
            perf_ord[e] = ++perf_seq;
        } else if (perf_held & PF_BIT(e)) {   /* ((2.0.2, #57) held as the layer locked: let go, it stays on, latched, */
            perf_latched |= PF_BIT(e);        /* so its next press or the layer closing turns it off (it stayed held */
            perf_held &= ~PF_BIT(e);          /* for good before, on every page) */
        }
        return;
    }
    if (down) {
        perf_held |= PF_BIT(e);
        perf_ord[e] = ++perf_seq;
    } else {
        perf_held &= ~PF_BIT(e);
    }
}

/* key k's note with the octave buttons at oct: QNT, ROOT, SCALE, TRN (KB_SILENT: a black key under WHITE). The keys
 * (kb_map) and the arp's latched keys (arp_list: as the keys play now, the octave they were pressed in) */
static uint32_t kb_pitch(const track_t *t, uint32_t k, int32_t oct)
{
    static const int8_t PLACE[12] = {0, 0, 1, 1, 2, 3, 2, 4, 3, 5, 4, 6};   /* among the keys of its colour from C */
    int32_t n = 53 + (int32_t)k, q = t->p[P_QUANT];
    if (q == QN_SNAP || q == QN_SEQ || q == QN_SEQT)    /* SNAP (and SEQ, SEQ+T): every key, rounded down */
        return (uint32_t)clamp(scale_snap(t, n + 12 * oct + t->p[P_TRANS]), 0, 127);
    if (q == QN_WHITE || q == QN_SOLO) {
        /* WHITE: C4 is the root, the white keys walk the scale (below C4 too), the black keys are silent. (2.1, #74)
         * SOLO: the white keys as WHITE; the black keys walk it too, five an octave, C#4 the root (SOLO_OCT up) */
        if (!key_black(k))
            n = kb_degree(t, PLACE[n % 12] + (n / 12 - 5) * 7);
        else if (q == QN_SOLO)
            n = kb_degree(t, PLACE[n % 12] + (n / 12 - 5) * 5) + 12 * SOLO_OCT;
        else
            return KB_SILENT;
    }
    return (uint32_t)clamp(n + 12 * oct + t->p[P_TRANS], 0, 127);
}

/* a stored value as the parameter takes it (projects, user presets, motion): inside d's range, and a retired
 * DRUM KIT (1..3) as the kit it plays, so KIT never holds one again. (SAMPLE / GRAIN's aliases keep their
 * number: they are what the sound was saved with, and play the original anyway) */
static int32_t param_fit(const param_desc_t *d, int32_t v)
{
    v = clamp(v, d->min, d->max);
    return d->names == N_DRUM_KIT ? enum_orig(d, v) : v;
}

/* a record of kind 0 (automation) or MOTION_LOCK on track t's step / id: a new one, or the one there (of either kind)
 * becomes this. 0 ok, 1 invalid, 2 the 64 are used (motion_full: "AUTOMATION FULL") */
static int motion_put(track_t *t, uint32_t step, uint32_t id, int16_t value, uint32_t kind)
{
    uint32_t k = trk_index(t), i, f;
    const param_desc_t *d;
    if (k >= NTRK || step >= NSTEP || !motion_param(id)) return 1;
    if ((motion_lost >> k) & 1u) { motion_full = 1; return 2; }   /* (phase 5: the pattern's own did not fit) */
    d = param_desc_of(eng_idx(t->eng_req), id);
    if (value < d->min || value > d->max || value < -64 || value > 127) return 1;
    value = (int16_t)param_fit(d, value);                    /* (a retired KIT: the kit it plays) */
    f = motion_guard();
    for (i = 0; i < motion.count; i++)
        if (motion.event[i].place == (k << 6 | step) && MOTION_ID(&motion.event[i]) == id) break;
    if (i == MOTION_MAX) { motion_full = 1; motion_unguard(f); return 2; }
    motion.event[i].place = (uint16_t)(k << 6 | step);
    motion.event[i].id = (uint8_t)id;
    motion.event[i].lock = kind != 0u;
    motion.event[i].value = (int8_t)value;                   /* (-64..127: checked above) */
    RING_PUBLISH();
    if (i == motion.count) motion.count++;
    motion.on |= (uint8_t)(1u << k);
    motion_unguard(f);
    return 0;
}

static int midi_enqueue(uint32_t pkt, uint32_t source)
{
    uint32_t at = mi_w % MQ;
    if (midi_in_overflow)
        return 0;
    if (mi_w - mi_r >= MQ) {
        midi_in_overflow = 1;
        return 0;
    }
    midi_in_q[at] = pkt;
    midi_in_ms[at] = fm1_ms;
    midi_in_source[at] = (uint8_t)source;
    RING_PUBLISH();
    mi_w++;
    return 1;
}

/* settings store a tagged id, THEME's (Skiff, R1: UI_THEME_TAG + index); earlier ids are migrated: the eleven palettes
 * before THEME (UI_PAL_TAG + index) and Felucca's oldest twenty (below 20); a palette that is gone is SKIFF */
static uint32_t palette_from_stored(uint32_t v)
{
    if (v >= UI_THEME_TAG && v - UI_THEME_TAG < NPALETTES) return v - UI_THEME_TAG;
    if (v >= UI_PAL_TAG && v - UI_PAL_TAG < 11u) return UI_PALETTE_MIGRATE11[v - UI_PAL_TAG];
    return v < 20u ? UI_PALETTE_MIGRATE20[v] : UI_SKIFF_INDEX;
}

/* (Skiff phase 5) the lists: id + 1 up to the pool (0 none; (#28) PAT_REST a REST: firmware before refuses a project
 * holding one), repeats - 1 up to 15 ((2.0) or REPS_CHAIN), each track on one of its entries, SONG 0 / 1 ((2.0) 2
 * ONCE; both refused before) */
static int proj_ent_ok(const project_t *q)
{
    uint32_t t, e;
    if (q->song > SONG_ONCE)
        return 0;
    for (t = 0; t < NTRK; t++) {
        if (q->cur[t] >= NENT)
            return 0;
        for (e = 0; e < NENT; e++)
            if (q->ent[t][e][0] > PAT_REST || (q->ent[t][e][1] > 15u && q->ent[t][e][1] != REPS_CHAIN))
                return 0;
    }
    return 1;
}

static int ota_erase(uint32_t off)
{
    if (off < T_AREA || off >= T_AREA_HI || (off & 0xFFFu)) { bad_erase++; return -8; }
    erases++;
    memset(nor + off, 0xFF, 4096);
    return 0;
}

/* '#' c1, '.' c2 (0: left as it is), z times its size */
static void cr_spritez(int32_t x, int32_t y, const uint8_t *art, uint16_t c1, uint16_t c2, int32_t z)
{
    const uint16_t cols[2] = {c1, c2};
    ui_sprite(x, y, art, c2 ? 2u : 1u, cols, z);
}

/* the SLOT patch p shows: the factory patch it equals (F n; looked for from SLOT s on), else OWN */
static int32_t fm6_match(const uint8_t *p, int32_t s)
{
    uint8_t v[FP_SIZE + 1u];
    uint32_t k, f = s >= 0 && s < (int32_t)FM6_NFACTORY ? (uint32_t)s : 0u;
    for (k = 0; k < FM6_NFACTORY; k++) {
        fm6_unpack(FM6_FACTORY[(f + k) % FM6_NFACTORY], v);
        if (!memcmp(v, p, FP_SIZE))
            return (int32_t)((f + k) % FM6_NFACTORY);
    }
    return FM6_OWN;
}

/* the engine's defaults and its first preset. With the audio IRQ off: the ISR sees the old engine with
 * its values or the new one with its own (voice.c engine_block), never one with the other's. 0 done; 1 refused (an
 * engine the track may not play: said, nothing changed, no undo copy) */
static int set_engine_of(track_t *t, uint32_t ei)
{
    const engine_t *e;
    uint32_t i;
#if !FELUCCA_FM4 && !FELUCCA_LEGACY
    if (ei % NENGINES == ENGI_DIGITAL)               /* ((2.0) DIGITAL (retired; the editor's SET, PRESET): FM6 */
        ei = ENGI_FM6;
#endif
    e = ENGINES[ei % NENGINES];
    if (!eng_allowed(trk_index(t), ei)) {
        eng_refused(ei);
        return 1;
    }
#if !FELUCCA_FM4 && FELUCCA_LEGACY
    if (ei % NENGINES == ENGI_DIGITAL) {             /* DIGITAL (retired): its first preset, as FM6 */
        fm4_load_preset(t, 0);
        return 0;
    }
#endif
    load_begin(t, UNDO_SOUND);
    fm1_irq_off();
    t->eng_req = (uint8_t)(ei % NENGINES);
    for (i = 0; i < 8u; i++)
        t->p[P_E0 + i] = e->edit[i].def;
    apply_preset_to(t, 0);
    fm1_irq_on();
    load_end(t);
    return 0;
}

/* save into copy `to` (0 A, 1 B; -1: the one that is not the current copy, as st_save) */
static int st_save_to(uint32_t obj, const void *src, uint32_t len, int to)
{
    uint32_t seq, base, off;
    int cur, rc;
    st_hdr_t h;
    if (obj >= OBJ_COUNT || len > ST_PAYLOAD_MAX || to > 1)
        return -1;
    cur = st_current(obj, &h);
    seq = cur < 0 ? 0u : h.seq;
    if (to < 0)
        to = cur == 0 ? 1 : 0;                        /* write the other copy */
    base = st_sector(obj, (uint32_t)to);
    for (off = 0; off < len; off++)
        st_buf[off] = ((const uint8_t *)src)[off];    /* the driver wants RAM sources */
    if ((rc = st_erase(base)) != 0)
        return rc;
    for (off = 0; off < len; off += 256u) {
        uint32_t n = len - off > 256u ? 256u : len - off;
        if ((rc = st_prog(base + ST_PAYLOAD_OFF + off, st_buf + off, n)) != 0)
            return rc;
    }
    h.magic = ST_MAGIC;
    h.type = (uint16_t)obj;
    h.slot = (uint16_t)to;
    h.seq = seq + 1u;
    h.len = len;
    h.crc = st_crc32(st_buf, len);
    h.rsv[0] = h.rsv[1] = 0xFFFFFFFFu;
    h.hcrc = st_crc32(&h, sizeof h - 4u);
    if ((rc = st_prog(base, &h, sizeof h)) != 0)       /* the commit record, last */
        return rc;
    {   /* read back: a write-protected or failing part must not report SAVED */
        st_hdr_t chk;
        uint32_t c = (uint32_t)to;
        if (st_head(obj, c, &chk) || memcmp(&chk, &h, sizeof h) || st_body(obj, c, &chk))
            return -7;
    }
    return 0;
}

static void ed_u28(uint32_t n)
{
    for (uint32_t i = 0; i < 4; i++) ed_b((n >> (i * 7)) & 127u);
}

/* pat_keep_rec; no slot free and the transport stopped: a chunk written first to make room */
static int pat_keep_now(uint32_t id, const uint8_t *r)
{
    return pat_keep_rec(id, r) && (transport_busy() || pat_flush_one() || pat_keep_rec(id, r));
}

static uint32_t ed_bk_r32(const uint8_t *p)
{
    return (uint32_t)p[0] | (uint32_t)p[1] << 7 | (uint32_t)p[2] << 14 | (uint32_t)p[3] << 21 | (uint32_t)p[4] << 28;
}

static int project_changed(void)                    /* (now, not as last looked: a dialog's question) */
{
    pj_at = 0;
    return project_dirty();
}

/* a step as STEP_SET / TRACK_STEP send it (na bytes): n, 4 notes, time, flags, vel, then (v5) the lane hits
 * and their accents: hit & 127, acc & 127, bit 7 of each (bit 0 hit, bit 1 acc), (v7) the chance, (RATCH, INFO
 * 52 01) the hits 1..4, (Skiff W1, INFO 43 01) FLAM 0/1, COND (TC_*), NUDGE + 32 (0..63); each value made valid.
 * 8 bytes (an editor of before the grid): the hits stay; without the chance, the ratchet or the rest the step keeps
 * its own (flags carry accent and slide only). (Skiff W1) The ratchet is set only when it changes: an editor of
 * before writes x1 back on a FLAM step, which kept its FLAM no longer. (2.0, #25, INFO 57 01 bit 6) Then its ties (bit
 * k: note k goes on from the step before; none on a step with hits or a TIE); a write without them (an editor of
 * before) leaves a step without hits none: that editor's step is whole */
static void ed_step_put(step_t *st, const uint8_t *a, uint32_t na)
{
    uint32_t i;
    st->n = (uint8_t)(a[0] > 4u ? 4u : a[0]);
    for (i = 0; i < 4u; i++)
        st->note[i] = a[1 + i] & 0x7Fu;
    st->time = (uint8_t)(a[5] > ST_REST ? ST_REST : a[5]);
    st->flags = (uint8_t)((a[6] & (SF_ACCENT | SF_SLIDE)) | (st->flags & (SF_RATCH | SF_FLAM)));   /* ((Skiff) FLAM kept) */
    st->vel = a[7] & 0x7Fu;
    if (na >= 11u) {
        st->hit = (uint8_t)((a[8] & 0x7Fu) | (a[10] & 1u) << 7);
        st->acc = (uint8_t)(((a[9] & 0x7Fu) | (a[10] & 2u) << 6) & st->hit);
    }
    if (na >= 12u) step_set_chance(st, a[11] <= 100u ? a[11] : 100u);
    if (na >= 13u && a[12] != step_ratchet(st)) step_set_ratchet(st, a[12]);
    if (na >= 16u) {                                  /* (Skiff W1) FLAM (on x1 only), COND, NUDGE */
        if (a[13] && step_ratchet(st) == 1u)
            st->flags |= SF_FLAM;
        else
            st->flags &= (uint8_t)~SF_FLAM;
        st->cond = (uint8_t)(a[14] < TC_COUNT ? a[14] : 0u);
        st->nudge = (int8_t)((a[15] > 63u ? 63 : (int32_t)a[15]) - 32);
    }
    if (!st->hit)                                     /* ((2.0, #25) acc there: the ties) */
        st->acc = (uint8_t)(na >= 17u && st->time != ST_TIE ? a[16] & ((1u << st->n) - 1u) : 0u);
    ui.force = 1;
}

/* (2.0) r as a version 6 record of the sound v (today's P_* order, each value inside its range): no pattern */
static void up_set_sound(up_rec_t *r, const int16_t *v)
{
    uint32_t s;
    r->ver = UP_VER_SID;
    r->np = (uint8_t)SID_COUNT;
    memset(r->sid, 0, sizeof r->sid);
    for (s = 0; s < SID_COUNT; s++)
        r->sid[s] = (uint8_t)(v[sid_p(s)] + 64);
}

/* main loop: editor frames first; anything else stays for ota_service() */
static void ed_service(void)
{
    const uint8_t *p;
    uint32_t n;
    ed_sync();                                             /* v2 pushes (while watched) */
    if (!ota_frame_get(&p, &n) || n < 4u || p[0] != ED_HDR0 || p[1] != ED_HDR1 || p[2] != ED_HDR2)
        return;
    ed_w.last_ms = fm1_ms;                                 /* any request keeps WATCH alive */
    if (p[3] >= ED_SMP_BEGIN) {                            /* large frames: handled in place, then freed */
        if (p[3] == ED_SMP_MIX && n > 4u)
            ed_smp_mix(p, n);                              /* ((#21) ed_smp_mix) */
        else
            ed_handle(p, n);
        ota_frame_done();
        return;
    }
    {
        static uint8_t f[64];
        uint32_t k = n > sizeof f ? sizeof f : n, i;
        for (i = 0; i < k; i++)
            f[i] = p[i];
        ota_frame_done();                                  /* free the frame buffer before replying */
        ed_handle(f, k);
    }
}

static int ota_send_msg(uint32_t cmd, const uint8_t *body, uint32_t n)   /* n <= 32 */
{
    uint32_t i, s = 0, w;
    ota_msg[0] = 0;
    ota_msg[1] = 0x59;
    ota_msg[2] = (uint8_t)cmd;
    ota_msg[3] = (uint8_t)n;
    ota_msg[4] = 0;
    ota_msg[5] = 0;
    for (i = 0; i < n; i++) {
        ota_msg[6 + i] = body[i];
        s += body[i];
    }
    ota_msg[6 + n] = (uint8_t)~s;
    ota_wire[0] = 0xF0;
    w = 1u + ota_pack7(ota_msg, 7u + n, ota_wire + 1);
    ota_wire[w++] = 0xF7;
    return ota_wire_send(ota_wire, w);
}

