        card_span_by(span_names, N_MSRC, 0, MS_N - 1);
        draw_column(1, "SOURCE", N_MSRC[clamp(s, 0, MS_N - 1)], "", s && !fx ? VR_LIVE : VR_DIM, -1, mod_src_icon(s));
        card_span_by(span_mod_dst, t, 0, MD_N - 1);
        draw_column(2, "DEST", mod_dst_name(t, d), "", d && !fx ? VR_LIVE : VR_DIM, -1, mod_dst_icon(t, d));
        param_format(&TP[id], a, val, &unit);
        card_span_of(&TP[id]);
        draw_column(3, "AMOUNT", val, unit, a && !(fx && mod_dead(t, r)) ? VR_LIVE : VR_DIM, RATIO(&TP[id], a),
                    mod_src_icon(MS_OFF));
        return;
    }
    if (step_page(cur_page()->graph) && lock_held()) {   /* a step held: what KNOB 1..4 lock (ui_input.c lock_turn) */
        uint64_t held = lock_held();
        uint32_t st = 0;
        while (!((held >> st) & 1u))
            st++;                                       /* (the first step held: its values) */
        for (c = 0; c < 4u; c++) {
            uint32_t id = lock_id(c);
            const param_desc_t *d;
            int16_t v;
            int on;
            if (id == 0xFFu) {
                draw_column(c, "", "", "", VR_THEME, -1, ICON_AUTO);
                continue;
            }
            d = track_desc(TSEL, id);
            on = motion_lock_get(TSEL, st, id, &v);
            if (!on)
                v = motion_base_value(TSEL, id);      /* not locked: the sound's own, DIM */
            param_format(d, v, val, &unit);
            card_span_of(d);
            draw_column(c, d->label, val, unit, on ? VR_LIVE : VR_DIM, RATIO(d, enum_rank(d, v)), param_icon(d, v));
        }
        return;
    }
    if (cur_page()->scope == SC_STEP && drum_track(TSEL)) {   /* the grid ((2.0) PRESETS the cursor): LANE, the cursor's
                                                         * HIT ACC, the selection's VELOCITY */
        const step_t *st = &TSEL->step[ui.cursor];
        uint32_t b = 1u << ui.lane, on = (step_lanes(st) & b) != 0u, ac = (step_accents(st) & b) != 0u;
        uint32_t f = sel_first(TSEL);
        draw_column(0, "LANE", drum_lane_name(TSEL, ui.lane), "", VR_LIVE, -1, ICON_AUTO);
        draw_column(1, "HIT", on ? "ON" : "--", "", on ? VR_LIVE : VR_DIM, -1, ICON_AUTO);
        draw_column(2, "ACC", ac ? "ON" : "--", "", ac ? VR_LIVE : VR_DIM, -1, ICON_AUTO);
        fmt_int(val, f < NSTEP ? (int32_t)step_vel(&TSEL->step[f]) : 0);
        draw_column(3, "VELOCITY", f < NSTEP ? val : "--", "", f < NSTEP ? VR_LIVE : VR_DIM,
                    f < NSTEP ? (int32_t)step_vel(&TSEL->step[f]) * 1000 / 127 : -1, ICON_AUTO);
        return;
    }
    if (cur_page()->scope == SC_STEP) {               /* (Skiff 2.0) NOTES: PITCH START LENGTH VELOCITY of the selection's
                                                        * first step (PITCH its lowest note selected, "+" the others
                                                        * selected); nothing selected: DIM "--" ("TIE": the cursor on
                                                        * one; the header has the cursor's step) */
        const track_t *t = TSEL;
        uint32_t f = sel_first(t), i, k, cnt = 0, lo = 128u;
        char u[8], sl[8];
        int32_t c;
        for (i = sel_lo(); f < NSTEP && i <= sel_hi(); i++)
            for (k = 0; sel_step(t, i) && k < t->step[i].n; k++)
                if (sel_voice(i, k) && !step_tied(&t->step[i], k)) {   /* ((2.0) a note going on: the one before's) */
                    cnt++;
                    if (i == f && t->step[i].note[k] < lo)
                        lo = t->step[i].note[k];
                }
        u[0] = 0;
        str_cpy(val, "--", sizeof val);
        if (lo < 128u)
            note_name(val, lo);
        if (cnt > 1u) {
            u[0] = '+';
            fmt_int(u + 1, (int32_t)cnt - 1);
        }
        draw_column(0, "PITCH", val, u, f < NSTEP ? VR_LIVE : VR_DIM, -1, ICON_AUTO);
        str_cpy(val, "--", sizeof val);
        sl[0] = 0;
        if (f < NSTEP) {                              /* ((2.0, #44) a chain's counted on: 69 /128) */
            uint32_t all, off = step_off(&all, 1);
            fmt_int(val, (int32_t)(off + f) + 1);
            fmt_kn(sl, -1, (int32_t)all);
        }
        draw_column(1, "START", val, sl, f < NSTEP ? VR_LIVE : VR_DIM, -1, ICON_AUTO);
        unit = "";
        c = f < NSTEP ? len_get(t, f) : 0;
        if (c >= LEN_STEPS - 1) {                     /* ((2.0) 100 % is 1 STEP: the default, the next 2 STEPS) */
            fmt_int(val, c - LEN_STEPS + 2);
            unit = c >= LEN_STEPS ? "STEPS" : "STEP";
        } else if (c) {
            param_format(track_desc(t, P_SGATE), (int16_t)c, val, &unit);
        } else {
            str_cpy(val, t->step[ui.cursor].time == ST_TIE ? "TIE" : "--", sizeof val);
        }
        draw_column(2, "LENGTH", val, unit, f < NSTEP ? VR_LIVE : VR_DIM, -1, ICON_AUTO);
        fmt_int(val, f < NSTEP ? (int32_t)step_vel(&t->step[f]) : 0);
        draw_column(3, "VELOCITY", f < NSTEP ? val : "--", "", f < NSTEP ? VR_LIVE : VR_DIM,
                    f < NSTEP ? (int32_t)step_vel(&t->step[f]) * 1000 / 127 : -1, ICON_AUTO);
        return;
    }
    for (c = 0; c < 4u; c++) {
        int16_t *vp;
        const param_desc_t *d = page_desc(cur_page(), c, &vp);
        if (cur_page()->graph == GR_SLOTS && c == 1u) {   /* ((Skiff U2) PROJECT: NAME, was EDIT; (1.2.1, #6) DELETE, */
            draw_act_column(1, ui.act == 2u && ui.act2 ? "NAME" : "DELETE",   /* one step further NAME) */
                            project_used((uint32_t)song.g[G_SLOT] - 1u) ? VR_THEME : VR_DIM, ICON_AUTO);
            continue;
        }
        if (cur_page()->graph == GR_SLOTS && c == 2u && !project_used((uint32_t)song.g[G_SLOT] - 1u)) {
            draw_act_column(2, "NEW", VR_THEME, ICON_AUTO);   /* ((1.2.1, #6) an empty slot: a blank project) */
            continue;
        }
        if ((cur_page()->graph == GR_LANES || cur_page()->graph == GR_LMIX) && c == 0u)   /* (LANE: above) */
            continue;
        if (!d || !d->label || d->label[0] == '-') {
            draw_column(c, "", "", "", VR_THEME, -1, ICON_AUTO);
            continue;
        }
        if ((act_cols() >> c) & 1u) {
            draw_act_column(c, d->label, VR_THEME, ICON_AUTO);
            continue;
        }
        param_format(d, *vp, val, &unit);
        card_mot_of(vp);                                /* (a global: never) */
        card_span_of(d);
        draw_column(c, (cur_page()->graph == GR_LANES || cur_page()->graph == GR_LMIX) && c == 1u ? "LEVEL" : d->label,
                    val, unit,                          /* ((phase 9) TUNE DECAY; (2.0) LANE MIX's PAN) */
                    card_dead(cur_page(), c) ? VR_DIM : VR_LIVE,
                    d->fmt == F_ENUM && d->max < 2 ? -1 : RATIO(d, enum_rank(d, *vp)), param_icon(d, *vp));
    }
}

static int32_t meter_px(int32_t a)                   /* |sample| (Q15) -> px: 60 dB over the slot */
{
    int32_t lg = 0, v;
    if (a < 64)
        return 0;
    while ((a >> lg) > 1)
        lg++;
    v = lg * 8 + (((a << 3) >> lg) & 7);             /* 8 log2(a): 48 (-54 dB) .. 128 (+6 dB) */
    return clamp((v - 48) * (TS_MH - 2) / 80, 0, TS_MH - 2);
}

/* a dotted outline (dark matter: there, but nothing shows), a dot every 3 px */
static void qk_dotframe(int32_t x, int32_t y, int32_t w, int32_t h, uint16_t c)
{
    int32_t i;
    for (i = 0; i < w; i += 3) {
        cv_rect(x + i, y, 1, 1, c);
        cv_rect(x + i, y + h - 1, 1, 1, c);
    }
    for (i = 0; i < h; i += 3) {
        cv_rect(x, y + i, 1, 1, c);
        cv_rect(x + w - 1, y + i, 1, 1, c);
    }
}

static int graph_project_used(uint32_t slot)
{
    static uint32_t ms, frame;
    static uint8_t mask, ready;
    if (!ready || fm1_ms - ms >= 500u || (ui.force && frame != ui.frame)) {
        uint32_t i; mask = 0;
        for (i = 0; i < 4u; i++) mask |= (uint8_t)((project_name(i, graph_pname[i]) != 0) << i);
        graph_pname_sig = fnv(2166136261u, graph_pname, sizeof graph_pname);
        ready = 1; ms = fm1_ms; frame = ui.frame;
    }
    return (mask >> (slot & 3u)) & 1u;
}

static void draw_graph(void)
{
    const page_t *pg = cur_page();
    const track_t *t = TSEL;
    uint16_t c = ux.quark ? T_THEME : T_TRK(song.sel);   /* Skiff: BLOCKS draws in the track's colour ((Skiff Q5) QUARK:
                                                      * cyan, an instrument's readouts, as the mockup) */
    uint32_t sig;
    int32_t pad = graph_pad();                       /* (Skiff) BLOCKS: the panel 16 px taller (ui.c foot_less): ADSR and
                                                      * LFO grow into it, the fixed layouts sit centred, pad lower */
    if (!ui.home && pg->graph == GR_TRK) {
        draw_tracks();
        return;
    }
    if (!ui.home && (pg->scope == SC_ENGINE || pg->graph == GR_SMIX) && ENGINES[t->eng_req % NENGINES] == &ENG_SAMPLE)
        sample_wave_tick(t);
    sig = graph_signature() + (ui.take_t ? take_box.gen * 2654435761u + 0x7A6Bu : 0u);   /* (Skiff: the TAKE box) */
    if (!ui.force && sig == ui.graph_sig)
        return;
    ui.graph_sig = sig;
    cv_begin(240, graph_h(), T_BG);
    if (ux.crypt) {                                  /* (Skiff C3) CRYPT: stone in a double frame */
        cr_stone(3, 0, 234, (int32_t)graph_h(), T_SURF);
        cr_frame2(3, 0, 234, (int32_t)graph_h(), T_LINE);
    } else
        cv_rrect(3, 0, 234, graph_h(), 5, T_SURF, T_BG);   /* the panel (MENU > LARGE: the strip) */
    if (ux.quark)                                    /* ((Skiff Q2) QUARK: an instrument's bracket corners) */
        qk_corners(3, 0, 234, (int32_t)graph_h(), T_DIM, 7);
    cv_bg = T_SURF;                                  /* (text drawn with cv_text lands on it) */
    cv_oy = GOY + pad;                               /* graphs on a 100 px scale */
    if (strip_kind() != SK_NONE) {                   /* MENU > LARGE: the strip */
        uint32_t k = strip_kind();
        cv_oy = k == SK_ADSR || k == SK_LFO ? 3 : k == SK_SCOPE ? 0 : pad;
        graph_ht = (int32_t)graph_h() - 6;
        if (k == SK_SCOPE) graph_scope(c);
        else if (k == SK_ADSR) graph_adsr(t, c);
        else if (k == SK_LFO) graph_lfo(t, c);
        else if (k == SK_STEPS) graph_steps(t, c);
        else graph_title();
        graph_ht = 100;
    } else if (ui.home) {
        cv_oy = 0;
        if (ui.home_scope)
            graph_scope(c);
        else
            graph_tracks();                          /* Skiff: the four tracks (ui_home.c) */
    } else {
        switch (pg->graph) {
        case GR_ADSR:
            cv_oy = GOY;
            graph_ht = 100 + 2 * pad;
            graph_adsr(t, c);
            graph_ht = 100;
            break;
        case GR_LFO:
            cv_oy = GOY;
            graph_ht = 100 + 2 * pad;
            graph_lfo(t, c);
            graph_ht = 100;
            break;
        case GR_STEPS:
            graph_steps(t, c);
            break;
        case GR_FEEL:                                /* (Skiff 2.0) FEEL: the tiles, each step's value (a drum track: */
            cv_oy = drum_track(t) ? pad : 0;         /* the grid (#10); the tiles centre themselves) */
            if (drum_track(t))
                graph_grid(t, c);
            else
                graph_tiles(t, c);
            break;
        case GR_ROLL:                                /* (Skiff 2.0) NOTES: the roll (a drum track: the grid) */
            cv_oy = pad;
            if (drum_track(t))
                graph_grid(t, c);
            else
                graph_roll(t, c);
            break;
        case GR_SCALE:
            graph_scale(t, c);
            break;
        case GR_CHORD:
            cv_oy = pad;
            graph_chord(t, c);
            break;
        case GR_FOLLOW:                              /* ((2.1) as CHORD's) */
            cv_oy = pad;
            graph_follow(t);
            break;
        case GR_FX:
            graph_fx(t, c);
            break;
        case GR_SLCR:
            graph_slicer(t, c);
            break;
        case GR_DUCK:                                /* (Skiff) */
            graph_duck(t, c);
            break;
        case GR_MOD:                                 /* ((2.0, D 1A) from the panel's top, as the mockup) */
            cv_oy = 0;
            graph_mod(t, c);
            break;
        case GR_BROWSE:
            cv_oy = pad;
            graph_browse();
            break;
        case GR_SLOTS:
            cv_oy = pad;
            graph_slots();
            break;
        case GR_USER:
            cv_oy = pad;
            graph_user();
            break;
        case GR_BANK:                                /* (Skiff phase 5) the pool view, from the panel's top (the mockup's) */
            cv_oy = 0;
            graph_bank();
            break;
        case GR_DXSND:                               /* (Skiff phase 7, 8; FM6 LAB) a sheet, from the panel's top */
        case GR_FMOP:
        case GR_FMALL:
            cv_oy = 0;
            sheet_of(pg->graph)->draw(t, c);
            break;
        case GR_SONG:                                /* (Skiff phase 5) the rows from the panel's top (the mockup's) */
            cv_oy = 0;
            graph_song();
            break;
        case GR_EVENTS:
            cv_oy = pad;
            graph_events();
            break;
        case GR_LANES:                               /* (Skiff U3, R6) */
            graph_lanes(t, c);
            break;
        case GR_LMIX:                                /* ((2.0, #36) LANE MIX) */
            graph_lmix(t, c);
            break;
        case GR_DRIVE:                               /* (Skiff phase 9; U5, V1: ui_pgraph.c, from the panel's top) */
            cv_oy = 0;
            graph_drive(t, c);
            break;
        case GR_INS:                                 /* (Skiff 1.3) */
            cv_oy = 0;
            graph_insert(t, c);
            break;
        case GR_DELAY:
            cv_oy = 0;
            graph_delay(c);
            break;
        case GR_REVERB:
            cv_oy = 0;
            graph_reverb(c);
            break;
        case GR_CHORUS:
            cv_oy = 0;
            graph_chorus(c);
            break;
        case GR_GLOBAL:
            cv_oy = 0;
            graph_global(c);
            break;
        case GR_VOICE:
            cv_oy = 0;
            graph_voice(t, c);
            break;
        case GR_VOICE2:
            cv_oy = 0;
            graph_voice2(t, c);
            break;
        case GR_ARP:
        case GR_ARP2:
            cv_oy = 0;
            graph_arp(t, c);
            break;
#if FELUCCA_SLICE
        case GR_SLICES:
            cv_oy = pad;
            graph_slices();
            break;
#endif
        default:
            if (pg->scope == SC_ENGINE && ENGINES[t->eng_req % NENGINES] == &ENG_WHEEL) graph_wheel(t, c);
            else if ((pg->scope == SC_ENGINE || pg->graph == GR_SMIX) && ENGINES[t->eng_req % NENGINES] == &ENG_SAMPLE &&
                     sample_wave.ready) graph_sample(c);   /* ((#21) SAMPLES: the sample's) */
            else if (pg->scope == SC_ENGINE && t->eng_req % NENGINES == ENGI_FM6) graph_fm6(t, c);   /* EDIT 1 and 2 */
            else if (analog_page(pg, t)) {           /* (Skiff U5) ANALOG's OSC and FLT */
                cv_oy = 0;
                if (pg->id[0] == P_E0) graph_osc(t, c);
                else graph_flt(t, c);
            }
#if FELUCCA_FM4
            else if ((pg->scope == SC_ENGINE || pg->id[0] == P_FM1_LEVEL) && t->eng_req % NENGINES == ENGI_DIGITAL)
                graph_fm(t, c);                      /* (OP LEVEL too: the levels on the chart) */
#endif
            else { cv_oy = 0; graph_scope(c); }   /* (it centres itself in the canvas) */
            break;
        }
    }
    cv_oy = 0;
    if (ui.take_t && (int32_t)graph_h() >= TB_Y + TB_H + 1)   /* (Skiff: the TAKE box, ui_take.c) */
        take_box_draw();
    cv_blit(0, graph_y());
}

static void wheel_render(track_t *t, voice_t *v, int32_t *out, uint32_t n, const vmod_t *m)
{
    const drw_trk_t *T = &drw_t[drw_part(t)];
    drw_vc_t *V = &((drw_vc_t *)eng_part(t))[(uint32_t)(v - t->v) % NVOICE];
    int32_t acc[CTL], perc1, clk0, clk1;
    uint32_t i, k;
    if (n > CTL)
        n = CTL;
    for (i = 0; i < n; i++)
        acc[i] = 0;
    perc1 = (int32_t)(((uint32_t)V->perc * T->pdec) >> 16);
    for (k = 0; k < DRW_NP; k++) {
        uint32_t x = m->inc, inc, ph = V->ph[k];
        int32_t g1 = T->g[k], g0 = V->gp[k], r;
        if ((int32_t)k == T->pk)
            g1 += mulq15(T->plev, perc1);
        while (x > DRW_FOLD_LIM[k])                     /* fold back above ~6 kHz */
            x >>= 1;
        inc = drw_ratio(k, x);
        r = inc < DRW_XOVER;                            /* 1: the low rotor */
        g1 = mulq15(g1, T->am[r]);
        inc += (uint32_t)((int32_t)(inc >> 16) * T->fm[r]);
        V->gp[k] = g1;
        if (!g0 && !g1) {
            V->ph[k] = ph + inc * n;
            continue;
        }
        if (g0 == g1) {
            for (i = 0; i < n; i++) {
                ph += inc;
                acc[i] += (SINE[ph >> 22] * g1) >> 15;
            }
        } else {                                        /* gain ramp over the block (CTL = 32) */
            int32_t gq = g0 << 5, dg = g1 - g0;
            for (i = 0; i < n; i++) {
                ph += inc;
                gq += dg;
                acc[i] += (SINE[ph >> 22] * (gq >> 5)) >> 15;
            }
        }
        V->ph[k] = ph;
    }
    V->perc = perc1;
    /* key click: high-passed noise, at the key contact and (half) at the release */
    if (V->gate && !v->gate) {
        V->gate = 0;
        V->clk = 16384;
    }
    clk0 = mulq15(V->clk, T->clk);
    if (clk0 > 16) {
        int32_t nst = V->nz, hp = V->hp, dc;
        V->clk = (V->clk * 3) >> 2;                     /* tau ~2.5 ms */
        clk1 = mulq15(V->clk, T->clk);
        dc = clk1 - clk0;
        clk0 <<= 5;
        for (i = 0; i < n; i++) {
            int32_t z = (int32_t)(noise32(&nst) >> 17) - 16384, y = z - hp;
            hp += y >> 3;
            clk0 += dc;
            acc[i] += (y * (clk0 >> 5)) >> 15;
        }
        V->nz = nst;
        V->hp = hp;
    }
    if (T->dg) {                                        /* overdrive */
        int32_t dg = T->dg, dcomp = T->dcomp;
        for (i = 0; i < n; i++)
            acc[i] = (softclip((acc[i] * dg) >> 9) * dcomp) >> 8;
    }
    for (i = 0; i < n; i++)                             /* acc: Q15 with headroom to 4.0 */
        out[i] += voice_amp(acc[i] >> 1, m, i) << 1;
}

/* once per block, before the voices: bar gains, percussion, click, drive, the rotors */
static void wheel_block(track_t *t)
{
    drw_trk_t *T = &drw_t[drw_part(t)];
    const int16_t *p = t->p;
    uint32_t k, perc = (uint32_t)p[P_E4] % 7u, rot = (uint32_t)p[P_E7] % 3u;
    int32_t s = 0, lv[DRW_NP];
    uint32_t norm;
    for (k = 0; k < DRW_NP; k++) {
        lv[k] = perc && k == DRW_NP - 1u ? 0 : DRW_LV[drw_level(p, k)];   /* PERC on: the 1' bar is off */
        s += lv[k];
    }
    /* sum of the gains = 2.4 s / (s + 1.5) (s in units of a full bar): one bar 0.96, three 1.6,
     * all nine 2.06 */
    norm = (uint32_t)(2u * 39322u * 32768u) / (uint32_t)(s + 49152);
    if (perc == 1u || perc == 2u || perc == 5u || perc == 6u)
        norm = (norm * 23170u) >> 15;                   /* normal percussion: the bars -3 dB */
    for (k = 0; k < DRW_NP; k++)
        T->g[k] = (int32_t)(((uint32_t)lv[k] * norm) >> 15);
    T->pk = perc ? (int32_t)(3u + ((perc - 1u) & 1u)) : DRW_NP;   /* 2ND: 4', 3RD: 2 2/3' */
    T->plev = perc == 3u || perc == 4u ? 12000 : 24000;
    T->pdec = perc >= 5u ? 65457u : 65219u;             /* tau 0.6 s / 0.15 s */
    T->clk = p[P_E5] * 180;
    if (p[P_E6]) {                                      /* y = 6 / (2 + g) tanh(g x / 2) */
        T->dg = 256 + p[P_E6] * 6;                      /* 1 .. 4 */
        T->dcomp = (6 * 256 * 256) / (512 + T->dg);
    } else {
        T->dg = 0;
    }
    /* rotors: each speed eases to its target (high rotor tau ~0.37 s, low ~1.5 s) */
    for (k = 0; k < 2u; k++) {
        int32_t sp, c, sn, dep;
        T->rsp[k] += (DRW_ROT_SPD[k][rot] - T->rsp[k]) >> (k ? 11 : 9);
        sp = T->rsp[k];
        T->rph[k] += (uint32_t)sp;
        sn = sine_i(T->rph[k]);
        c = sine_i(T->rph[k] + 0x40000000u);
        dep = k ? 7000 : 13000;                         /* AM depth: low rotor 21 %, high 40 % */
        T->am[k] = 32767 - mulq15(dep, (32767 - c) >> 1);
        T->fm[k] = (sn * (sp >> (k ? 17 : 16))) >> 15;  /* Doppler: +-0.5 % fast (high), +-0.2 % (low) */
    }
    T->rwet += ((rot ? 32767 : 0) - T->rwet) >> 5;      /* ~25 ms in or out */
    for (k = 0; k < 2u; k++) {
        T->am[k] = 32767 - mulq15(T->rwet, 32767 - T->am[k]);
        T->fm[k] = mulq15(T->fm[k], T->rwet);
    }
}

/* the voice's amplitude: the hit, not the ADSR (which still runs, held at full so a release never ends
 * it). A voice that plays no lane any more, or whose drum has rung out, ends here */
static int32_t drum_amp(track_t *t, voice_t *v, int32_t adsr)
{
    const drum_lane_t *L = drum_lane_of(t, v);
    (void)adsr;
    if (!v->active)                                      /* (taken for another part: env_tick ended it) */
        return 0;
    if (!L || (drum_user(t->p) ? v->s[6] == 1 : !L->v.live && !L->v.trig)) {   /* ((#35) a user kit's: its sample over) */
        v->active = v->gate = 0;
        v->stage = 0;
        v->env = 0;
        return 0;
    }
    v->env = 1 << 24;
    return 32767;
}

/* the GM drum map, the first C (key 7) is the kick (C2, 36) */
static int32_t drum_keys(const track_t *t, uint32_t k)
{
    (void)t;
    return clamp(29 + 12 * song.octave + (int32_t)k, 0, 127);
}

static void fm6_render(track_t *t, voice_t *v, int32_t *out, uint32_t len, const vmod_t *m)
{
    fm6_note_t *n = fm6_note_of(t, v);
    uint32_t tr = (uint32_t)(t - trk), i;
    const uint8_t *p;
    int32_t bus[FM6_N], lf, fb, lvl, k, a, da;
    if (!n || !n->live || len != FM6_N)
        return;
    p = fm6_eff[tr].p;
    if (!v->gate && n->down)
        fm6_note_key(n, p, 0);
    lf = fm6_note_logfreq(m->pitch16 + (p[FP_TRNSP] - 24) * 16, m->fine);
    fb = clamp(fm6_eff[tr].fb + ((m->shape - (64 << 8)) >> 11), 0, 7);
    lvl = clamp(t->p[P_E2], -64, 63) * 24 + clamp(m->cutoff >> 8, -150, 150) * 16;   /* microsteps */
    if (!fm6_note_compute(n, p, bus, fm6_lfo_v[tr], fm6_lfo_d[tr], lf, fm6_eff[tr].alg, fb, fm6_eff[tr].dt, lvl << 16))
        return;                                         /* every carrier below the threshold */
    /* the voice's amplitude ramp x VOICE_FS (one carrier at full: VOICE_FS / 2), six voices in unison ~ one */
    k = t->p[P_VOICE] == V_UNISON ? VOICE_FS * 2 / 5 : VOICE_FS;
    a = mulq15(m->amp0, k);
    da = (mulq15(m->amp1, k) - a) >> FM6_LG_N;
    for (i = 0; i < FM6_N; i++) {
        int32_t x = bus[i] - n->dc;
        n->dc += x >> 10;                                 /* a one-pole high-pass, ~7 Hz: FM puts sidebands at 0 Hz */
        a += da;
        out[i] += (int32_t)(((int64_t)x * a) >> 26);
    }
}

/* every carrier has gone silent for good: the voice ends (voice.c, engine_t.done) */
static int fm6_done(track_t *t, voice_t *v)
{
    fm6_note_t *n = fm6_note_of(t, v);
    uint32_t tr = (uint32_t)(t - trk);
    if (!n || !n->live)
        return 1;
    if (!fm6_note_done(n, fm6_eff[tr].p, fm6_eff[tr].alg))
        return 0;
    n->live = 0;
    return 1;
}

/* (FM6 LAB T) the sound under a line (PITCH, LFO; CRYPT and QUARK's D: the loudest carrier), column x from y to the
 * foot: RAISE; CRYPT the ASCII shade (a dot every 4 px, every 6th column), NEON the sun's bands, QUARK a Monte Carlo
 * fill */
static void fm_under(int32_t x, int32_t y, int32_t foot)
{
    if (ux.crypt) {
        if ((x - FM_X0) % 6 == 0)
            for (y = (y + 4) & ~3; y < foot; y += 4)
                cv_pset(x, y, T_DIM);
    } else
        pg_under(x, y, FM_GY, foot, T_RAISE);
}

/* block b's column: the held part, the release, each on a log axis (the attack gets room) */
static int32_t fm_warp(const fm_sim_t *s, int32_t b)
{
    int32_t l0 = fm_log2(FM_TAU);
    if (b <= s->held)
        return (FM_HW - 1) * (fm_log2((uint32_t)b * 256u + FM_TAU) - l0) / (fm_log2((uint32_t)s->held * 256u + FM_TAU) - l0);
    return FM_HW + (FM_XW - FM_HW - 1) * (fm_log2((uint32_t)(b - s->held) * 256u + FM_TAU) - l0) /
                       (fm_log2((uint32_t)(s->n - s->held) * 256u + FM_TAU) - l0);
}

/* the note (MIDI 60 + TRANSP, velocity 100), its key up at `held` (< 0: found: once every sounding carrier holds,
 * a quarter more, at least 0.35 s; none by 4 s: at 4 s) and its release (the carriers 60 dB down, at most 2 s) */
static void fm_run(fm_sim_t *s, const track_t *t, int32_t held)
{
    fm6_env_t e[6];
    fm6_penv_t pe;
    uint32_t k, prev[6], pp = 0;
    int32_t b, note, cap = held >= 0 ? held : 4 * 1378, last[7];
    note = 60 + s->q[FP_TRNSP] - 24;
    for (k = 0; k < 6u; k++) {
        fm6_op_env_init(&e[k], s->q + (5u - k) * FP_OP, note, 100);
        prev[k] = 0;
        if (held >= 0) {
            memset(&s->op[k], 0, sizeof s->op[k]);
            memset(s->op[k].end, 0xFF, 4);
            fm_bp(&s->op[k], 0, 0);
        }
    }
    fm6_penv_init(&pe, s->q);
    if (held >= 0) {
        memset(&s->pitch, 0, sizeof s->pitch);
        memset(s->pitch.end, 0xFF, 4);
        fm_bp(&s->pitch, 0, pe.level >> 8);
    }
    for (b = 0;; b++) {
        uint32_t quiet = 1, hold = 1;
        if (b == cap) {
            if (held < 0) {                             /* none held by 4 s */
                fm_run(s, t, cap);
                return;
            }
            for (k = 0; k < 6u; k++)
                fm6_env_key(&e[k], s->q + (5u - k) * FP_OP, 0);
            fm6_penv_key(&pe, s->q, 0);
        }
        for (k = 0; k < 6u; k++) {
            int32_t lv = last[k] = fm6_env_get(&e[k], s->q + (5u - k) * FP_OP) >> 8;
            if ((s->car >> k & 1u) && (s->live >> k & 1u)) {
                hold &= e[k].ix >= 3u;
                quiet &= lv < FM_TOP - FM_SPAN;
            }
            if (held >= 0 && (e[k].ix != prev[k] || b + 1 == held)) {
                fm_env_line_t *l = &s->op[k];
                uint32_t j;
                fm_bp(l, b + 1, lv);
                for (j = prev[k]; j < e[k].ix && j < 4u; j++)
                    l->end[j] = (uint8_t)(l->n - 1u);
                prev[k] = e[k].ix;
            }
        }
        {
            int32_t pv = last[6] = fm6_penv_get(&pe, s->q) >> 8;
            if (held >= 0 && (pe.ix != pp || b + 1 == held)) {
                uint32_t j;
                fm_bp(&s->pitch, b + 1, pv);
                for (j = pp; j < pe.ix && j < 4u; j++)
                    s->pitch.end[j] = (uint8_t)(s->pitch.n - 1u);
                pp = pe.ix;
            }
        }
        if (held < 0 && hold) {                         /* found: run it again with the key up there */
            b++;
            fm_run(s, t, b + b / 4 > 482 ? b + b / 4 : 482);
            return;
        }
        if (held >= 0 && b >= cap && (quiet || b - cap >= 2 * 1378)) {
            s->n = b + 1;
            break;
        }
    }
    s->held = cap;
    for (k = 0; k < 7u; k++) {                          /* the end of each line, and every point's column */
        fm_env_line_t *l = k < 6u ? &s->op[k] : &s->pitch;
        uint32_t j;
        if (l->n && l->i[l->n - 1u] < s->n) {
            if (l->n == FM_NBP)
                l->n--;
            fm_bp(l, s->n, last[k]);
        }
        for (j = 0; j < l->n; j++)
            l->x[j] = (int16_t)fm_warp(s, l->i[j]);
    }
}

/* the caption's right: the length; and the key (SINE, the ramp, FM) */
static void fm_caption(const fm_sim_t *s, const uint16_t *sh)
{
    char b[16];
    uint32_t j;
    fm_secs(b, s->n);
    GFX_HOOK_ALIGN(0, FM_CY, 0, FM_CY + 12, AL_V, "FM6 graph caption on its row");
    cv_text_r(229, FM_CY + CAP_IN(S, 12), &AF_S, b, T_MID, T_SURF);
    if (!sh)
        return;
    cv_text_r(129, FM_CY + CAP_IN(S, 12), &AF_S, "SINE", T_DIM, T_SURF);
    for (j = 0; j < 12u; j++)
        cv_rect(132 + (int32_t)j * 3, FM_CY + 3, 3, 7, sh[j]);
    cv_text(171, FM_CY + CAP_IN(S, 12), &AF_S, "FM", T_DIM);
}

/* carrier c's heat at column x, 0 .. 11: the strongest modulator feeding it (and the feedback, by FB / 7, where its
 * operator is c or one of them), its level over its top 60 dB, the square root (a little FM is heard at once) */
static uint32_t fm_heat(const fm_sim_t *s, uint32_t c, uint32_t fed, int32_t x)
{
    static const uint8_t SQ[11] = {1, 5, 13, 26, 43, 64, 89, 119, 153, 191, 233};   /* 256 ((i + 0.5) / 11)^2 */
    int32_t best = 0, n;
    uint32_t k, f = fm6_fb_op(s->alg), i;
    for (k = 0; k < 6u; k++)
        if ((fed >> k & 1u) && (s->live >> k & 1u)) {
            n = clamp((fm_at_x(&s->op[k], x) + s->modlvl - (FM_TOP - FM_HEAT)) * 16 / (FM_HEAT >> 4), 0, 256);
            best = n > best ? n : best;
        }
    if (s->fb && (s->live >> f & 1u) && (f == c || (fed >> f & 1u))) {
        int32_t lv = fm_at_x(&s->op[f], x) + ((s->car >> f & 1u) ? 0 : s->modlvl);
        n = clamp((lv - (FM_TOP - FM_HEAT)) * 16 / (FM_HEAT >> 4), 0, 256) * (int32_t)s->fb / 7;
        best = n > best ? n : best;
    }
    for (i = 0; i < 11u && best >= SQ[i]; i++)
        ;
    return i;
}

static void fm_line(const fm_env_line_t *l, int32_t dy, int32_t w, uint16_t c, const uint8_t *shade, const uint16_t *sh)
{
    uint32_t j;
    for (j = 1; j < l->n; j++)
        fm_seg(FM_X0 + l->x[j - 1u], fm_lvy(l->v[j - 1u]) + dy, FM_X0 + l->x[j], fm_lvy(l->v[j]) + dy, w, c, shade, sh);
}

static void fm_draw(uint32_t pg, const track_t *t, uint16_t c)
{
    static fm_sim_t s __attribute__((section(".pool")));   /* (1.2 KB: off the stack and the ISR's globals) */
    uint16_t sh[12];
    uint32_t w = fm_ui[1 + pg] % FM_NWIN;
    fm_ramp(sh);
    if (pg && w == FMW_ALGO) {
        fm_algo(t, c);
    } else if (!pg && (w == FMW_KEYS || w == FMW_MORE)) {
        fm_ops(&s, t);
        fm_tabs(&s, sh, 0);
        fm_keys(c);
    } else {
        fm_sim(&s, t);
        if (pg && (w == FMW_LFO || w == FMW_DEPTH))
            fm_lfo(&s, c);
        else if (pg)
            fm_pitch(&s, c, w);
        else {
            fm_tabs(&s, sh, w == FMW_TONE);
            fm_lines(&s, sh, w);
        }
    }
    fm_scroll(w);
}
